	dels    int
}

func (h *recHost) Get(s, a string) (string, error) {
	if h.blockOn == "get" { <-h.gate }
	h.mu.Lock(); defer h.mu.Unlock()
	if v, ok := h.sets[a]; ok { return v, nil }
	return "", ErrNotFound
}
func (h *recHost) Set(s, a, v string) error {
	if h.blockOn == "set" { <-h.gate }
	h.mu.Lock(); defer h.mu.Unlock(); h.sets[a] = v; return nil
}
func (h *recHost) Delete(s, a string) error {
	h.mu.Lock(); defer h.mu.Unlock(); h.dels++; delete(h.sets, a); return nil
}

// (1) Abandoned Set completes later; a Delete issued while stuck is refused without trying.
func TestAuditLateSetAndRefusedDelete(t *testing.T) {
	shortKeyringTimeout(t)
	h := &recHost{gate: make(chan struct{}), blockOn: "set", sets: map[string]string{}}
	prev := SwapHostStoreForTest(h)
	t.Cleanup(func() { SwapHostStoreForTest(prev) })
	k := NewKeyringStorage("ctx")
	err := k.Save("https://g", "tok-secret")
	if !errors.Is(err, ErrKeyringUnresponsive) { t.Fatalf("save err=%v", err) }
	if strings.Contains(err.Error(), "tok-secret") { t.Errorf("secret in err") }
	derr := k.Delete("https://g") // logout while stuck
	t.Logf("delete while stuck: %v, backend deletes=%d", derr, h.dels)
	close(h.gate)
	time.Sleep(50 * time.Millisecond)
	h.mu.Lock(); v := h.sets["ctx/https://g"]; h.mu.Unlock()
	t.Logf("AUDIT: after logout, secret in keyring = %v (late Set landed)", v != "")
}

